b", "kickoff_time": "20:20:00", "court": 2, "publication_state": "draft", "schedule_status": "cancelled", "phase": "cancel"}, {"id": "14b3f0af-f1ca-4512-9dcd-82c6d402e3eb", "home_team_id": "e5b8d7c3-89e1-430a-94b4-afd7b42cbe43", "away_team_id": "38580a95-ab89-5ddd-a71d-c31ed05de4bd", "kickoff_time": "21:00:00", "court": 1, "publication_state": "draft", "schedule_status": "cancelled", "phase": "cancel"}, {"id": "be7d32d5-07ed-4f0d-9633-5036f1b3c6f9", "home_team_id": "997291fd-33ff-40cc-9fd8-be732f6e07ca", "away_team_id": "57b0b3f9-24a5-4ea7-9e1b-fd3faa90891c", "kickoff_time": "21:00:00", "court": 2, "publication_state": "draft", "schedule_status": "cancelled", "phase": "cancel"}, {"id": "fcdb7960-d519-4dfb-8e4b-d8177c3777ea", "home_team_id": "bd834936-1b8a-4dd7-9013-d4b792862b67", "away_team_id": "f0402dd7-5aa2-4a6b-98ee-6d8663c6a76c", "kickoff_time": "19:00:00", "court": 1, "publication_state": "draft", "schedule_status": "cancelled", "phase": "cancel"}, {"id": "a6519dee-3399-4dcb-bd1b-0aa7916d26de", "home_team_id": "3a9c1f75-ecbe-4c05-85b9-bacfd65fb7ff", "away_team_id": "997291fd-33ff-40cc-9fd8-be732f6e07ca", "kickoff_time": "19:00:00", "court": 2, "publication_state": "draft", "schedule_status": "cancelled", "phase": "cancel"}, {"id": "7c790c6c-85e8-4e98-a710-7ee667abb05b", "home_team_id": "8c867565-d3f7-4445-b799-a2b0e15b510d", "away_team_id": "d16662f1-9520-4f2a-b30b-ede1db30f28d", "kickoff_time": "19:40:00", "court": 1, "publication_state": "draft", "schedule_status": "cancelled", "phase": "cancel"}, {"id": "0a909789-6112-4840-aa7f-ba512b3cc057", "home_team_id": "38580a95-ab89-5ddd-a71d-c31ed05de4bd", "away_team_id": "b78bd03e-1e87-4cf7-8a0e-409f5de92959", "kickoff_time": "19:40:00", "court": 2, "publication_state": "draft", "schedule_status": "cancelled", "phase": "cancel"}, {"id": "a4f527e2-aef0-49d5-b098-9260cf038654", "home_team_id": "57b0b3f9-24a5-4ea7-9e1b-fd3faa90891c", "away_team_id": "ec502bdd-d24e-48cf-84fb-f27f11387fda", "kickoff_time": "20:20:00", "court": 1, "publication_state": "draft", "schedule_status": "cancelled", "phase": "cancel"}, {"id": "2992fa61-a51c-475d-bf01-e24b63533c92", "home_team_id": "544ff92b-0753-4e4f-9feb-bdcdf9c74a98", "away_team_id": "44d7e359-957a-4b38-8a0a-40b698d609c9", "kickoff_time": "20:20:00", "court": 2, "publication_state": "draft", "schedule_status": "cancelled", "phase": "cancel"}, {"id": "b372dc32-2555-4d03-8e37-c7b19f9964e7", "home_team_id": "0ad2ddbd-80e1-40f5-bb80-2e756a3d9419", "away_team_id": "8464062e-5897-4573-a075-d283236dd36c", "kickoff_time": "21:00:00", "court": 1, "publication_state": "draft", "schedule_status": "cancelled", "phase": "cancel"}, {"id": "59435eb0-81b6-46a7-8b3e-3f9ffadfc43b", "home_team_id": "8434b3b9-091d-4d8b-ab29-f857807d1c3b", "away_team_id": "e5b8d7c3-89e1-430a-94b4-afd7b42cbe43", "kickoff_time": "21:00:00", "court": 2, "publication_state": "draft", "schedule_status": "cancelled", "phase": "cancel"}]'::jsonb) AS x(id uuid,home_team_id uuid,away_team_id uuid,kickoff_time time,court integer,publication_state text,schedule_status text,phase text);
CREATE TEMP TABLE m16_scores ON COMMIT DROP AS SELECT * FROM jsonb_to_recordset('[{"id": "0638c88d-ff1e-419c-88d6-a9efebdead2d", "home_score": 3, "away_score": 7}, {"id": "d9f713df-b04c-4d09-adf3-2aa174fa9c80", "home_score": 2, "away_score": 10}, {"id": "9320a43a-da54-4130-906a-93d8486e949f", "home_score": 6, "away_score": 6}, {"id": "c76a8458-67ad-4093-8728-a571d40f59eb", "home_score": 9, "away_score": 8}, {"id": "351c7bb2-bd05-4b64-8bc9-ca94db75b658", "home_score": 5, "away_score": 5}, {"id": "c9a6ae3d-69bf-4e2a-bca6-793de1138928", "home_score": 7, "away_score": 12}, {"id": "77449678-b266-4658-a615-4d3340ad7903", "home_score": 8, "away_score": 2}, {"id": "6368bf78-92b6-4222-8ad2-1bdcddadbc45", "home_score": 7, "away_score": 3}]'::jsonb) AS x(id uuid,home_score integer,away_score integer);
DO $$BEGIN
 IF (SELECT md5(jsonb_agg(to_jsonb(x) ORDER BY id)::text) FROM(SELECT id,competition_season_id,legacy_id,round_number,round_label,match_date,kickoff_time,court,home_team_id,away_team_id,publication_state,schedule_status,schedule_version,updated_at,stage FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled')x) IS DISTINCT FROM '5e4af5611156479ea860bb445307da4e' OR (SELECT md5(jsonb_agg(to_jsonb(x) ORDER BY id)::text) FROM(SELECT id,competition_season_id,legacy_id,name,status,kit_colour,standings_eligible,profile_version,updated_at FROM public.teams WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef')x) IS DISTINCT FROM 'f67a0549c1dacf6f4677b0046cfb3c4e' THEN RAISE EXCEPTION 'Monday baseline changed or already applied';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.competition_seasons WHERE id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND lifecycle='active' AND publication_state='published') THEN RAISE EXCEPTION 'Edition state changed';END IF;
 IF EXISTS(SELECT 1 FROM public.fixture_change_sets WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND status IN('draft','pending_review')) THEN RAISE EXCEPTION 'Pending fixture work';END IF;
 IF EXISTS(SELECT 1 FROM public.result_versions WHERE fixture_id IN(SELECT id FROM m16_scores UNION SELECT id FROM m16_target)) THEN RAISE EXCEPTION 'Result work exists on affected rows';END IF;
 IF (SELECT count(*) FROM m16_target)<>102 OR (SELECT count(*) FROM m16_target WHERE phase='past')<>2 OR (SELECT count(*) FROM m16_target WHERE phase='future')<>47 OR (SELECT count(*) FROM m16_target WHERE phase='cancel')<>53 OR (SELECT count(*) FROM m16_scores)<>8 THEN RAISE EXCEPTION 'Unexpected proposal size';END IF;
 IF EXISTS(SELECT 1 FROM m16_scores p JOIN public.fixtures f ON f.id=p.id WHERE f.match_date<>'2026-11-16' OR f.round_number<>5 OR f.competition_season_id<>'62ce7ec9-459e-4acf-bec5-c6734a3199ef') THEN RAISE EXCEPTION 'Result fixture mismatch';END IF;
END $$;
-- Free only the changed future slots atomically; cancelled rows remain preserved.
UPDATE public.fixtures f SET publication_state='draft' FROM m16_target p WHERE f.id=p.id AND p.phase='future';
UPDATE public.fixtures f SET publication_state='draft',schedule_status='cancelled' FROM m16_target p WHERE f.id=p.id AND p.phase='cancel';
UPDATE public.fixtures f SET home_team_id=p.home_team_id,away_team_id=p.away_team_id,kickoff_time=p.kickoff_time,court=p.court,publication_state='published',schedule_status='scheduled' FROM m16_target p WHERE f.id=p.id AND p.phase IN('past','future');
INSERT INTO public.result_versions(fixture_id,revision,status,home_score,away_score) SELECT id,1,'published',home_score,away_score FROM m16_scores;
UPDATE public.teams SET status='withdrawn',standings_eligible=false,profile_version=profile_version+1 WHERE id IN('bd834936-1b8a-4dd7-9013-d4b792862b67','997291fd-33ff-40cc-9fd8-be732f6e07ca');
DO $$BEGIN
 IF EXISTS(SELECT 1 FROM m16_fixtures_before b FULL JOIN public.fixtures f USING(id) LEFT JOIN m16_target p ON p.id=b.id WHERE CASE WHEN p.id IS NULL THEN to_jsonb(b) IS DISTINCT FROM to_jsonb(f)
 ELSE (to_jsonb(b)-'home_team_id'-'away_team_id'-'kickoff_time'-'court'-'publication_state'-'schedule_status'-'schedule_version'-'updated_at') IS DISTINCT FROM (to_jsonb(f)-'home_team_id'-'away_team_id'-'kickoff_time'-'court'-'publication_state'-'schedule_status'-'schedule_version'-'updated_at') OR row(f.home_team_id,f.away_team_id,f.kickoff_time,f.court,f.publication_state,f.schedule_status) IS DISTINCT FROM row(p.home_team_id,p.away_team_id,p.kickoff_time,p.court,p.publication_state,p.schedule_status) OR f.schedule_version<>b.schedule_version+CASE WHEN p.phase='future' THEN 2 ELSE 1 END END) THEN RAISE EXCEPTION 'Unexpected fixture change';END IF;
 IF EXISTS(SELECT 1 FROM m16_results_before b LEFT JOIN public.result_versions v USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(v)) THEN RAISE EXCEPTION 'Existing results changed';END IF;
 IF (SELECT count(*) FROM public.result_versions)<>(SELECT count(*)+8 FROM m16_results_before) OR (SELECT count(*) FROM m16_scores p JOIN public.result_versions v ON v.fixture_id=p.id WHERE v.status='published' AND v.revision=1 AND v.home_score=p.home_score AND v.away_score=p.away_score AND v.forfeit_side IS NULL AND v.published_at IS NOT NULL)<>8 THEN RAISE EXCEPTION 'Result publication failed';END IF;
 IF EXISTS(SELECT 1 FROM m16_teams_before b FULL JOIN public.teams t USING(id) WHERE CASE WHEN b.id IN('bd834936-1b8a-4dd7-9013-d4b792862b67','997291fd-33ff-40cc-9fd8-be732f6e07ca') THEN (to_jsonb(b)-'status'-'standings_eligible'-'profile_version'-'updated_at') IS DISTINCT FROM (to_jsonb(t)-'status'-'standings_eligible'-'profile_version'-'updated_at') OR t.status<>'withdrawn' OR t.standings_eligible OR t.profile_version<>b.profile_version+1 ELSE to_jsonb(b) IS DISTINCT FROM to_jsonb(t) END) THEN RAISE EXCEPTION 'Unexpected team change';END IF;
 IF EXISTS(SELECT 1 FROM m16_notes_before b FULL JOIN public.team_fixture_notes t USING(team_id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) OR EXISTS(SELECT 1 FROM m16_preferences_before b FULL JOIN public.team_kickoff_preferences t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Private preferences changed';END IF;
 IF EXISTS(SELECT 1 FROM m16_audit_before b LEFT JOIN public.admin_audit_log t USING(id) WHERE to_jsonb(b) IS DISTINCT FROM to_jsonb(t)) THEN RAISE EXCEPTION 'Existing audit changed';END IF;
 IF (SELECT count(*) FROM public.teams WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND status='active')<>14 OR (SELECT count(*) FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled')<>187 THEN RAISE EXCEPTION 'Roster or fixture count failed';END IF;
 IF EXISTS(SELECT t.id FROM public.teams t LEFT JOIN public.fixtures f ON t.id IN(f.home_team_id,f.away_team_id) AND f.publication_state='published' AND f.schedule_status='scheduled' WHERE t.competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND t.status='active' GROUP BY t.id HAVING count(f.id)<>26) THEN RAISE EXCEPTION '26-game total failed';END IF;
 IF EXISTS(SELECT 1 FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' GROUP BY least(home_team_id,away_team_id),greatest(home_team_id,away_team_id) HAVING count(*)>2) THEN RAISE EXCEPTION 'Pair exceeds two meetings';END IF;
 IF EXISTS(SELECT 1 FROM public.fixtures f JOIN public.teams t ON t.id IN(f.home_team_id,f.away_team_id) WHERE f.competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND f.publication_state='published' AND f.schedule_status='scheduled' AND f.round_number>5 AND t.status<>'active') THEN RAISE EXCEPTION 'Withdrawn team remains scheduled';END IF;
 IF EXISTS(SELECT round_number FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' AND round_number>5 GROUP BY round_number HAVING count(*)<>7) THEN RAISE EXCEPTION 'Future round size failed';END IF;
 IF EXISTS(SELECT round_number,team FROM(SELECT round_number,home_team_id team FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled' UNION ALL SELECT round_number,away_team_id FROM public.fixtures WHERE competition_season_id='62ce7ec9-459e-4acf-bec5-c6734a3199ef' AND publication_state='published' AND schedule_status='scheduled')x GROUP BY round_number,team HAVING count(*)<>1) THEN RAISE EXCEPTION 'Duplicate team in round';END IF;
END $$;
SELECT txid_current() AS transaction_id,(SELECT count(*) FROM m16_target) AS changed_fixture_rows,(SELECT count(*) FROM m16_scores) AS published_results;
COMMIT;
